static const int CAP_HEIGHT[QDOS_PADFACE__COUNT] = {10, 8};

const qdos_padglyph* qdos_padfont_glyph(qdos_padface face, unsigned char ch) {
	if (ch < QDOS_PADFONT_FIRST || ch > QDOS_PADFONT_LAST)
		return NULL;

	const qdos_padglyph* table = (face == QDOS_PADFACE_SHIFT) ? GLYPHS_SHIFT : GLYPHS_CAP;
	return &table[ch - QDOS_PADFONT_FIRST];
}

const uint8_t* qdos_padfont_coverage(qdos_padface face) {
	return (face == QDOS_PADFACE_SHIFT) ? COVERAGE_SHIFT : COVERAGE_CAP;
}

int qdos_padfont_cap_height(qdos_padface face) {
	if (face < 0 || face >= QDOS_PADFACE__COUNT)
		return 0;
	return CAP_HEIGHT[face];
}

int qdos_padfont_advance(qdos_padface face, const char* text) {
	int total = 0;
	for (const char* p = text; *p != '\0'; p++) {
		const qdos_padglyph* g = qdos_padfont_glyph(face, (unsigned char)*p);
		if (g != NULL)
			total += g->advance;
	}
	return total;
}
